import {googlePriceQuestion} from './google-pricing.js';
export function initGooglePricing({market,node,api,getData,validate,begin,current,onQuery,onUse,notify}){
 const status=market.querySelector('#research-status'),output=market.querySelector('#automatic-prices'),button=market.querySelector('#research'),connection=node('details','google-pricing-connection');
 connection.innerHTML='<summary>Conectar Google para precios automáticos</summary><p>Solo se configura una vez. Crea una clave en Google AI Studio y escríbela aquí. Se guarda en el servidor y nunca aparece en la web cliente.</p><p><a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">Obtener clave de Google ↗</a> · <a href="https://ai.google.dev/gemini-api/docs/pricing#gemini-2.5-flash-lite" target="_blank" rel="noopener noreferrer">Consultar cuota gratuita vigente ↗</a></p><p>Usa un proyecto sin facturación para permanecer en la cuota gratuita. Si se agota, la consulta se detendrá. No se cambia automáticamente a otro modelo.</p><label>Clave de Google<input type="password" autocomplete="off" spellcheck="false" placeholder="Escribe tu clave de Google" data-google-key></label><button type="button" data-connect-google>Guardar conexión</button><p data-google-state role="status"></p>';
 const key=connection.querySelector('[data-google-key]'),connect=connection.querySelector('[data-connect-google]'),state=connection.querySelector('[data-google-state]');market.append(connection);key.addEventListener('input',e=>e.stopPropagation());key.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();connect.click();}});
 async function refresh(){try{const config=await api('admin/pricing-connection');state.textContent=config.configured?'Google conectado. Las consultas se realizan automáticamente.':'Falta conectar Google una sola vez.';return config.configured;}catch{state.textContent='No se pudo comprobar la conexión.';return false;}}
 connection.addEventListener('toggle',()=>{if(connection.open)refresh();});
 connect.onclick=async()=>{if(!key.value.trim()){notify('Escribe la clave de Google en este campo; no la envíes por el chat.',{type:'warning'});return;}connect.disabled=true;try{await api('admin/pricing-connection','POST',{apiKey:key.value.trim()});key.value='';await refresh();notify('Conexión guardada. Ya puedes obtener los tres precios con el botón.',{type:'success'});connection.open=false;}catch(e){notify(e.message,{type:'error'});}finally{connect.disabled=false;}};
 function render(result){output.replaceChildren();for(const group of result.valuation||[]){const grid=node('div','price-strategies');for(const scenario of group.scenarios){const card=node('article','price-strategy '+scenario.key),use=node('button','','Usar este precio');use.type='button';use.onclick=()=>onUse(scenario.price,group.currency);card.append(node('span','',scenario.label),node('strong','',(group.currency==='BOB'?'Bs ':'US$ ')+scenario.price.toLocaleString('en-US')),node('p','',scenario.reason),use);grid.append(card);}output.append(grid);}if(result.explanation){const detail=node('details'),summary=node('summary','','Motivos de los precios sugeridos'),text=node('p','',result.explanation);text.style.whiteSpace='pre-wrap';detail.append(summary,text);output.append(detail);}if(result.results?.length){const sources=node('div','pricing-google-sources');sources.append(node('h3','','Fuentes consultadas por Google'));for(const row of result.results){const a=node('a','',row.title);a.href=row.url;a.target='_blank';a.rel='noopener noreferrer';sources.append(a);}output.append(sources);}}
 button.onclick=async()=>{if(validate().length){notify('Corrige primero los datos de la ficha.',{type:'warning'});return;}const data=getData();if(!data.make||!data.name||!data.year){notify('Completa marca, modelo y año.',{type:'warning'});return;}const generation=begin(),question=googlePriceQuestion(data);onQuery();button.disabled=true;output.replaceChildren();status.textContent='Google está buscando y preparando los tres precios…';try{if(!await refresh()){if(generation!==current())return;connection.open=true;status.textContent='Conecta Google una sola vez. Después, este botón obtendrá los tres precios automáticamente.';return;}const result=await api('admin/research','POST',data);if(generation!==current()||question!==googlePriceQuestion(getData()))return;status.textContent=result.notice;render(result);}catch(e){if(generation===current()){status.textContent=e.message;}}finally{if(generation===current())button.disabled=false;}};
 return{reset(){key.value='';connection.open=false;}};
}
